package com.tripnest.controller; import com.tripnest.dto.ApiDtos.UserView; import com.tripnest.repository.UserRepository; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users") public class UserController{final UserRepository repo; public UserController(UserRepository r){repo=r;} @GetMapping("/me") public UserView me(Authentication a){var u=repo.findByEmail(a.getName()).orElseThrow();return new UserView(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name());}}
